import { existsSync, readFileSync } from 'node:fs';
import { afterEach, describe, expect, it, vi } from 'vitest';
import { inSeason, knownSports } from './sportSeasons';

/*
 * The demo shim, pinned.
 *
 * Two things are worth a test here and they are different kinds of thing. One
 * is the shim's own judgement — which pages count as the demo, and what it does
 * with a file that has been mangled. The other is the committed file itself:
 * public/oh/demo.json is generated by hand-run script and read by four store
 * functions, so a regeneration that changes its shape should fail here rather
 * than on a prospect's phone.
 *
 * Everything is loaded through a fresh module instance because loadDemo
 * memoizes for the life of the page, which is the right behaviour there and
 * would make these tests depend on their own order.
 */

const DEMO_FILE = new URL('../../public/oh/demo.json', import.meta.url);
const committed = () => JSON.parse(readFileSync(DEMO_FILE, 'utf8')) as Record<string, unknown>;

const dataFile = (slug: string) => new URL(`../../public/oh/data/${slug}.json`, import.meta.url);
const directoryIndex = () =>
  JSON.parse(readFileSync(new URL('../../public/oh/index.json', import.meta.url), 'utf8')) as {
    schools: Array<{ slug: string; name: string }>;
  };

/** What the generator dresses Millbrook in, as the validators hand it back. */
const MILLBROOK_COLORS = { ground: '#c65a12', accent: '#1a1a1a', text: '#000000', nickname: 'Tigers' };

/** The invented conference, by the slugs the generator gives it. */
const RIVALS = [
  'ashcombe-demo',
  'bellhaven-demo',
  'cedar-ridge-demo',
  'elmbrook-demo',
  'marlow-central-demo',
];

type Page = { pathname?: string; search?: string };

/*
 * A stand-in for this origin.
 *
 * The demo file answers everything the demo draws. The directory and the
 * forecast file are stubbed only so a test can prove they are never asked:
 * every URL requested is recorded in `__asked`.
 */
const load = async (body: unknown, page: Page = {}, weather: unknown = {}) => {
  vi.resetModules();
  vi.stubGlobal('location', { pathname: page.pathname ?? '/oh/demo/', search: page.search ?? '' });
  const jar: Record<string, string> = {};
  const asked: string[] = [];
  vi.stubGlobal('__asked', asked);
  vi.stubGlobal('localStorage', {
    getItem: (k: string) => jar[k] ?? null,
    setItem: (k: string, v: string) => {
      jar[k] = v;
    },
    removeItem: (k: string) => {
      delete jar[k];
    },
  });
  vi.stubGlobal(
    'fetch',
    vi.fn(async (url: string) => {
      const path = String(url).split('?')[0];
      asked.push(path);
      if (path === '/oh/demo.json') return { ok: true, json: async () => body };
      if (path === '/oh/weather.json') return { ok: true, json: async () => weather };
      const season = path.match(/^\/oh\/data\/([a-z0-9-]+)\.json$/);
      if (season && existsSync(dataFile(season[1]))) {
        const raw = readFileSync(dataFile(season[1]), 'utf8');
        return { ok: true, json: async () => JSON.parse(raw) };
      }
      return { ok: false, json: async () => null };
    }),
  );
  return import('./demo');
};

afterEach(() => {
  vi.unstubAllGlobals();
});

describe('which page is the demo', () => {
  it('knows the path, with or without the trailing slash', async () => {
    for (const pathname of ['/oh/demo', '/oh/demo/', '/oh/demo/index.html']) {
      const { isDemo } = await load(committed(), { pathname });
      expect(isDemo()).toBe(true);
    }
  });

  it('accepts ?demo as an alias, so a link cannot land on the directory', async () => {
    for (const search of ['?demo', '?demo=1', '?demo=yes']) {
      const { isDemo } = await load(committed(), { pathname: '/oh/', search });
      expect(isDemo(), search).toBe(true);
    }
  });

  it('reads ?demo=false as somebody turning it off', async () => {
    for (const search of ['?demo=false', '?demo=0', '?demo=no', '?demo=OFF']) {
      const { isDemo } = await load(committed(), { pathname: '/oh/', search });
      expect(isDemo(), search).toBe(false);
    }
  });

  it('leaves every other page alone', async () => {
    for (const page of [
      { pathname: '/oh/' },
      { pathname: '/oh/demonstration/' },
      { pathname: '/oh/', search: '?manage' },
      { pathname: '/' },
    ]) {
      const { isDemo } = await load(committed(), page);
      expect(isDemo()).toBe(false);
    }
  });

  it('is false off a page altogether, which is where the tests run', async () => {
    vi.resetModules();
    vi.unstubAllGlobals();
    const { isDemo } = await import('./demo');
    expect(isDemo()).toBe(false);
  });
});

/*
 * Whether the file was written with the autumn on.
 *
 * The generator has two honest outputs and they look nothing alike. Written
 * between August and November it produces a volleyball season under way — half
 * played, half to come. Written between December and July it produces the
 * next autumn as fixtures with **nothing** played, because a season cannot both
 * carry results and sit in months eight to eleven when today is February, and
 * the hub would otherwise print "Starts in August" over a row of January scores.
 *
 * So "no results anywhere" is a correct file half the year and a broken one the
 * other half, and the tests below have to ask which half before they judge. The
 * day it was written is on the file for exactly this reason.
 */
const bornInSeason = (): boolean =>
  inSeason('volleyball', Number((committed() as { generatedOn: string }).generatedOn.slice(5, 7)));

describe('the committed file', () => {
  it('reads as Millbrook, a school that does not exist, with three sports', async () => {
    const { loadDemo, DEMO_SLUG } = await load(committed());
    const demo = await loadDemo();

    expect(demo).not.toBeNull();
    expect(DEMO_SLUG).toBe('millbrook-demo');
    expect(demo!.slug).toBe(DEMO_SLUG);
    expect(demo!.school).toEqual({ slug: DEMO_SLUG, name: 'Millbrook', city: 'Millbrook' });
    expect(demo!.sportNames).toEqual(['football', 'volleyball', 'basketball']);
    for (const sport of demo!.sportNames) {
      expect(demo!.sports[sport].players.length).toBeGreaterThan(0);
    }
  });

  it('wears its own colors and a crest the database would have accepted', () => {
    const raw = committed() as { colors: unknown; logo: string };
    // Orange and black, like the paying school it is modelled on — and not
    // that school's own orange.
    expect(raw.colors).toEqual(MILLBROOK_COLORS);
    expect((raw.colors as { ground: string }).ground).not.toBe('#c75000');
    expect(raw.logo).toMatch(/^data:image\/png;base64,/);
    expect(raw.logo.length).toBeLessThan(500_000);
  });

  /*
   * Existence only, never contents: the directory's files are rewritten by a
   * cron job with no test step. What matters is that nothing invented here is
   * a school somebody actually attends.
   */
  it('borrows no real school', () => {
    const raw = committed() as { slug: string; league: { name: string; members: string[] } };
    expect(raw.league.name).toBe('Riverbend Athletic Conference');
    expect([...raw.league.members].sort()).toEqual([...RIVALS].sort());

    const real = new Set(directoryIndex().schools.map((s) => s.slug));
    for (const slug of [raw.slug, ...raw.league.members]) {
      expect(slug.endsWith('-demo'), slug).toBe(true);
      expect(real.has(slug), slug).toBe(false);
      expect(existsSync(dataFile(slug)), slug).toBe(false);
    }
    // "Tigers" is allowed: it is Millbrook's own nickname, said after its name
    // the way the app says a paid school's. Springfield, its crest file and its
    // players are not.
    expect(JSON.stringify(raw)).not.toMatch(/springfield|tigers-logo|marcus bell/i);
  });

  /*
   * A fictional school has no directory file, so everything the football tabs
   * draw has to be in this one: the school's season, every rival's, and a
   * forecast on the next fixture.
   */
  it('bakes the whole conference’s football, each game the same from both sides', async () => {
    const { loadDemo, demoSeason, demoWeather, DEMO_SLUG } = await load(committed());
    const demo = await loadDemo();
    const members = [DEMO_SLUG, ...RIVALS];

    for (const slug of members) {
      const season = await demoSeason(slug);
      expect(season, slug).not.toBeNull();
      expect(season!.school.slug).toBe(slug);
      expect(season!.games).toHaveLength(10);
      const played = season!.games.filter((g) => g.result);
      expect(season!.record).toEqual({
        won: played.filter((g) => g.result!.won).length,
        lost: played.filter((g) => !g.result!.won).length,
        played: played.length,
      });
      for (const g of season!.games) {
        if (!g.opponentSlug) continue;
        const back = demo!.seasons[g.opponentSlug].games.find((o) => o.week === g.week)!;
        expect(back.opponentSlug, `${slug} week ${g.week}`).toBe(slug);
        expect(back.date).toBe(g.date);
        expect(back.home).toBe(!g.home);
        expect(back.result?.us).toBe(g.result?.them);
        expect(back.result?.them).toBe(g.result?.us);
      }
    }

    const mine = (await demoSeason(DEMO_SLUG))!;
    for (const rival of RIVALS) {
      expect(mine.games.some((g) => g.opponentSlug === rival), rival).toBe(true);
    }
    expect(demo!.sports.football.schedule).toBeNull();

    // The forecast belongs to the next unplayed game and to nobody else.
    const next = mine.games.find((g) => !g.result);
    const forecast = await demoWeather(DEMO_SLUG);
    if (next) expect(forecast!.date).toBe(next.date);
    expect(await demoWeather(RIVALS[0])).toBeNull();
  });

  /*
   * A prospect who types a jersey number should find somebody, so the squad has
   * to read like a varsity roster and not a sketch of one.
   */
  it('fields a believable football squad, with no stats carried on the players', () => {
    const raw = committed() as {
      sports: Record<string, { players: Array<Record<string, unknown>> }>;
    };
    const football = raw.sports.football.players;

    // A believable small-school varsity, not a sketch.
    expect(football.length).toBeGreaterThanOrEqual(25);
    expect(new Set(football.map((p) => p.number)).size).toBe(football.length);

    // Stats live in their own file, as a paid school's do, and reach a player
    // only through the page's matcher — never as fields on the roster.
    for (const [sport, entry] of Object.entries(raw.sports)) {
      for (const p of entry.players) {
        expect(Object.keys(p).some((k) => /stat/i.test(k)), `${sport} #${p.number}`).toBe(false);
      }
    }
    expect(raw.sports.volleyball.players.length).toBeGreaterThanOrEqual(10);
    expect(raw.sports.basketball.players.length).toBeGreaterThanOrEqual(10);
  });

  /*
   * The conference twice over in both pasted sports, checked against the names
   * the baked seasons give the rivals.
   */
  it('pastes the whole conference into both schedules, twice', async () => {
    const { loadDemo } = await load(committed());
    const demo = (await loadDemo())!;
    const names = RIVALS.map((slug) => demo.seasons[slug].school.name);
    for (const sport of ['volleyball', 'basketball']) {
      const opponents = demo.sports[sport].schedule!.map((r) => r.opponent);
      for (const name of names) {
        expect(opponents.filter((o) => o === name), `${sport} ${name}`).toHaveLength(2);
      }
    }
  });

  /*
   * The invariant the generator is anchored to produce: a score is only ever
   * printed on a day that has been.
   *
   * Checked as an ordering rather than against the clock, deliberately. The
   * file is static and drifts, and a test that read `new Date()` would turn
   * that expected drift into a red build. What must never be true, at any
   * distance from the generation, is a scored match dated after an unscored
   * one; that is a generator bug rather than staleness.
   */
  it('puts every result behind every fixture in the pasted schedules', async () => {
    const { loadDemo } = await load(committed());
    const demo = await loadDemo();

    for (const [sport, entry] of Object.entries(demo!.sports)) {
      const rows = entry.schedule ?? [];
      const scored = rows.filter((r) => r.score).map((r) => r.date);
      const ahead = rows.filter((r) => !r.score).map((r) => r.date);
      expect(scored.every((s) => ahead.every((a) => s < a)), sport).toBe(true);
    }

    // Volleyball owes results only when the autumn was on — and then both
    // kinds, because a school that wins everything reads as a brochure.
    const volleyball = demo!.sports.volleyball.schedule!;
    const results = volleyball.filter((r) => r.score);
    if (bornInSeason()) {
      expect(results.some((r) => r.score!.us > r.score!.them)).toBe(true);
      expect(results.some((r) => r.score!.us < r.score!.them)).toBe(true);
    } else {
      expect(results).toHaveLength(0);
    }
    expect(volleyball.some((r) => !r.score)).toBe(true);
  });

  /*
   * The file is generated in one sport-season and read in another, and the hub
   * prints "In season" or "Starts in November" out of its own fixed table. This
   * holds the committed dates to that table as it stood on the day they were
   * written — `generatedOn`, rather than the clock the suite happens to run on,
   * because the file is static and the point is what the generator produced.
   */
  it('never writes a season the hub would contradict', () => {
    // Read straight off the committed file rather than through loadDemo, which
    // carries the dates forward to today — what is being checked here is what
    // the generator wrote, on the day it wrote it.
    const raw = committed() as unknown as {
      generatedOn: string;
      sports: Record<string, { schedule: Array<{ date: string; score?: unknown }> | null }>;
    };
    const month = Number(raw.generatedOn.slice(5, 7));

    for (const [sport, entry] of Object.entries(raw.sports)) {
      for (const r of entry.schedule ?? []) {
        if (inSeason(sport, month)) continue;
        // Out of season on the day it was written, a sport may have no results
        // and may only be dated inside its own months.
        expect(!!r.score, `${sport} ${r.date}`).toBe(false);
        expect(inSeason(sport, Number(r.date.slice(5, 7))), `${sport} ${r.date}`).toBe(true);
      }
    }

    const football = raw as unknown as {
      slug: string;
      seasons: Record<string, { games: Array<{ date: string; result?: unknown }> }>;
    };
    for (const g of football.seasons[football.slug].games) {
      if (inSeason('football', month)) continue;
      expect(!!g.result, `football ${g.date}`).toBe(false);
      expect(inSeason('football', Number(g.date.slice(5, 7))), `football ${g.date}`).toBe(true);
    }
  });

  /*
   * The generator is a .mjs script that cannot import this bundle's TypeScript,
   * so it keeps its own copy of the month table and this holds the two
   * together. Read out of the source text rather than imported, because
   * importing the script runs it — it resizes a crest and writes a file.
   */
  it('keeps the generator’s copy of the month table honest', () => {
    const src = readFileSync(new URL('../../scripts/build-demo.mjs', import.meta.url), 'utf8');
    const block = src.match(/const SPORT_MONTHS = \{([\s\S]*?)\n\};/);
    expect(block, 'SPORT_MONTHS is no longer where this test looks for it').not.toBeNull();

    const rows = [...block![1].matchAll(/^\s*(\w+): \[([\d, ]+)\],$/gm)];
    expect(rows.length).toBeGreaterThan(0);

    for (const [, sport, list] of rows) {
      expect(knownSports(), sport).toContain(sport);
      const copied = list.split(',').map((n) => Number(n.trim()));
      for (let month = 1; month <= 12; month += 1) {
        expect(copied.includes(month), `${sport} month ${month}`).toBe(inSeason(sport, month));
      }
    }
  });
});

/*
 * Carrying the calendar forward.
 *
 * The file is committed and then sits still while the world moves, and the
 * screen splits Played from Coming up on whether a game has a score rather than
 * on its date — so without this the demo starts listing last Tuesday's match as
 * coming up. These are the only tests here that name a day, and they name a
 * made-up one rather than reading the clock.
 *
 * The file is read as it was on the day it was written: the clock is set to
 * `generatedOn` while loadDemo runs, so its own carry-forward is a no-op and
 * every shift below is measured from the file as committed.
 */
describe('the calendar, weeks after it was written', () => {
  const day = (iso: string) => new Date(`${iso}T00:00:00Z`);
  const born = () => (committed() as { generatedOn: string }).generatedOn;
  const later = (days: number) =>
    new Date(day(born()).getTime() + days * 86_400_000).toISOString().slice(0, 10);

  const asWritten = async (body: unknown = committed()) => {
    const mod = await load(body);
    vi.useFakeTimers({ toFake: ['Date'] });
    vi.setSystemTime(day(born()));
    try {
      return { ...mod, demo: (await mod.loadDemo())! };
    } finally {
      vi.useRealTimers();
    }
  };

  type Rows = Array<{ date: string; score?: unknown }>;
  const rowsOf = (demo: { sports: Record<string, { schedule: Rows | null }> }, sport: string) =>
    demo.sports[sport].schedule!;
  const monthOf = (date: string) => Number(date.slice(5, 7));

  it('leaves a file generated today exactly as it is', async () => {
    const { demo, shiftToNow, weeksBehind } = await asWritten();
    expect(weeksBehind(demo, day(born()))).toBe(0);
    expect(shiftToNow(demo, day(born()))).toBe(demo);
  });

  it('lands volleyball’s split on today while its season lasts', async () => {
    const { demo, shiftToNow } = await asWritten();
    for (const when of [later(3), later(10)]) {
      const rows = rowsOf(shiftToNow(demo, day(when)), 'volleyball');
      for (const r of rows) {
        if (r.score) expect(r.date < when, `${when}: ${r.date} has a score`).toBe(true);
        else expect(r.date >= when, `${when}: ${r.date} has no score`).toBe(true);
      }
    }
  });

  it('moves a played schedule by whole weeks, so a Tuesday match stays on a Tuesday', async () => {
    const { demo, shiftToNow } = await asWritten();
    const before = rowsOf(demo, 'volleyball').map((r) => r.date);
    const after = rowsOf(shiftToNow(demo, day(later(17))), 'volleyball').map((r) => r.date);

    for (let i = 0; i < before.length; i += 1) {
      expect(day(after[i]).getUTCDay(), before[i]).toBe(day(before[i]).getUTCDay());
      const weeks = (day(after[i]).getTime() - day(before[i]).getTime()) / (7 * 86_400_000);
      expect(Number.isInteger(weeks), before[i]).toBe(true);
    }
  });

  /*
   * The bug this shape exists to stop: one delta, set by volleyball's results,
   * applied to basketball too. Four weeks on, basketball opened on Christmas
   * Day; seven weeks on, in January under a hub saying "In season"; by
   * December volleyball was printing last week's results under "Starts in
   * August". Basketball has nothing played, so it stays where the generator
   * put it, and volleyball never leaves its own months.
   */
  it('moves each sport by its own results, and never out of its own months', async () => {
    const { demo, shiftToNow } = await asWritten();
    const basketball = rowsOf(demo, 'basketball').map((r) => r.date);

    for (const when of ['2026-11-05', '2026-11-20', '2026-12-10', '2027-03-01', later(120)]) {
      const moved = shiftToNow(demo, day(when));

      const hoops = rowsOf(moved, 'basketball').map((r) => r.date);
      expect(hoops, when).toEqual(basketball);
      expect(inSeason('basketball', monthOf(hoops[0])), `${when}: opens ${hoops[0]}`).toBe(true);

      for (const r of rowsOf(moved, 'volleyball')) {
        expect(inSeason('volleyball', monthOf(r.date)), `${when}: ${r.date}`).toBe(true);
      }
    }
  });

  it('leaves a file with nothing played on it exactly where it was written', async () => {
    // A file generated out of season is all fixtures, each already dated inside
    // its sport's months by the generator; moving it could only move it out.
    const raw = committed() as unknown as {
      sports: Record<string, { schedule: Array<Record<string, unknown>> | null }>;
      seasons: Record<string, { games: Array<Record<string, unknown>> }>;
    };
    for (const entry of Object.values(raw.sports)) {
      for (const r of entry.schedule ?? []) delete r.score;
    }
    // Football's results are baked now too, and count as played just the same.
    for (const season of Object.values(raw.seasons)) {
      for (const g of season.games) delete g.result;
    }
    const { demo, shiftToNow, weeksBehind } = await asWritten(raw);

    for (const when of ['2027-03-01', '2027-11-11', '2030-01-20']) {
      expect(weeksBehind(demo, day(when)), when).toBe(0);
      expect(shiftToNow(demo, day(when)), when).toBe(demo);
    }
  });

  it('carries a baked season and its forecast along together', async () => {
    // Grafted over what the file bakes, so the dates are the test's own.
    const base = committed() as { slug: string; generatedOn: string };
    const played = later(-1);
    const next = later(7);
    const body = {
      ...base,
      weather: { date: next, code: 2, tempF: 63, precipChance: 20, windMph: 9, day: false, at: `${next}T19:00` },
      seasons: {
        [base.slug]: {
          school: { slug: base.slug, name: 'Millbrook', city: 'Millbrook' },
          games: [
            { week: 1, date: played, home: true, opponent: 'A', result: { us: 1, them: 0, won: true } },
            { week: 2, date: next, home: true, opponent: 'B' },
          ],
          record: { won: 1, lost: 0, played: 1 },
        },
      },
    };
    const { demo, shiftToNow } = await asWritten(body);
    const moved = shiftToNow(demo, day(later(15)));
    const movedNext = moved.seasons[base.slug].games[1].date;

    expect(movedNext).not.toBe(next);
    expect(moved.weather!.date).toBe(movedNext);
    expect(moved.weather!.at.startsWith(movedNext)).toBe(true);
  });

  it('keeps football’s split on today for three weeks after it was written', async () => {
    const { demo, shiftToNow } = await asWritten();
    const hadResults = demo.seasons[demo.slug].games.some((g) => g.result);
    for (const days of [8, 15, 22]) {
      const today = later(days);
      const games = shiftToNow(demo, day(today)).seasons[demo.slug].games;
      if (!hadResults) continue; // written out of season: nothing to carry
      const played = games.filter((g) => g.result).map((g) => g.date);
      const ahead = games.filter((g) => !g.result).map((g) => g.date);
      expect(played.every((d) => d < today), `+${days} played`).toBe(true);
      expect(ahead.every((d) => d >= today), `+${days} ahead`).toBe(true);
    }
  });

  it('never drags a file backwards for a clock that is behind', async () => {
    const { demo, weeksBehind } = await asWritten();
    expect(weeksBehind(demo, day('2020-01-01'))).toBe(0);
  });
});

describe('what the store guards ask for', () => {
  it('hangs the conference on football and on nothing else', async () => {
    const { demoRosterBody, DEMO_SLUG } = await load(committed());

    const football = (await demoRosterBody(DEMO_SLUG, 'football')) as Record<string, unknown>;
    expect(football.league).not.toBeNull();
    // Football's fixtures come from the directory, exactly as a real paid
    // school's do — there is nothing pasted for it.
    expect(football.schedule).toBeNull();

    const basketball = (await demoRosterBody(DEMO_SLUG, 'basketball')) as Record<string, unknown>;
    expect(basketball.league).toBeNull();
    expect(Array.isArray(basketball.schedule)).toBe(true);
  });

  it('answers for the demo school only', async () => {
    const { demoRosterBody, demoIdentity, demoWeather } = await load(committed());

    expect(await demoRosterBody('poland-seminary-poland', 'football')).toBeNull();
    expect(await demoIdentity('poland-seminary-poland')).toBeNull();
    expect(await demoWeather('poland-seminary-poland')).toBeNull();
  });

  it('answers nothing for a sport the school does not sell', async () => {
    const { demoRosterBody, DEMO_SLUG } = await load(committed());
    expect(await demoRosterBody(DEMO_SLUG, 'bowling')).toBeNull();
  });

  it('has no kept identity until the file has landed', async () => {
    const { keptDemoIdentity, loadDemo, DEMO_SLUG } = await load(committed());

    expect(keptDemoIdentity(DEMO_SLUG)).toBeNull();
    await loadDemo();
    expect(keptDemoIdentity(DEMO_SLUG)).not.toBeNull();
  });
});

/*
 * The guards, from the store side.
 *
 * This block deliberately does not mock ./supa the way rosterStore.test.ts
 * does. The demo has to work in a build with no Supabase variables at all —
 * which is exactly how CI runs — and the guards sit above the supaAvailable
 * gate precisely so that it does. Getting a roster back here, with no database
 * configured and no rpc mocked, is that claim being demonstrated rather than
 * asserted.
 */
describe('the store, in demo mode', () => {
  const stores = async () => {
    const { DEMO_SLUG } = await import('./demo');
    return {
      DEMO_SLUG,
      store: await import('./store'),
      rosterStore: await import('./rosterStore'),
    };
  };

  it('serves the roster and the identity out of the baked file, through the real validators', async () => {
    await load(committed());
    const { DEMO_SLUG, rosterStore } = await stores();

    const identity = await rosterStore.loadSchoolSports(DEMO_SLUG);
    expect(identity!.sports).toHaveLength(3);
    expect(identity!.colors).toEqual(MILLBROOK_COLORS);
    expect(identity!.logo).toMatch(/^data:image\/png;base64,/);

    const roster = await rosterStore.loadSchoolRoster(DEMO_SLUG, 'volleyball');
    expect(roster!.players).toHaveLength(12);
    expect(roster!.schedule).toHaveLength(14);
    // Only football carries a conference, and this one is volleyball.
    expect(roster!.league).toBeNull();

    const football = await rosterStore.loadSchoolRoster(DEMO_SLUG, 'football');
    expect(football!.league!.name).toBe('Riverbend Athletic Conference');
    expect(football!.league!.members).toHaveLength(5);
  });

  it('serves the season and the forecast from the file, and asks the directory for nothing', async () => {
    await load(committed(), {}, { 'millbrook-demo': { date: '2026-01-01' } });
    const { DEMO_SLUG, store } = await stores();
    localStorage.setItem('oh.school', DEMO_SLUG);

    const season = await store.loadSeason(DEMO_SLUG);
    expect(season.school).toEqual({ slug: DEMO_SLUG, name: 'Millbrook', city: 'Millbrook' });
    for (const rival of RIVALS) {
      expect((await store.loadSeason(rival)).school.slug).toBe(rival);
    }
    const forecast = await store.loadWeather(DEMO_SLUG);
    expect(forecast).not.toBeNull();
    expect(forecast!.date).not.toBe('2026-01-01');

    const asked = (globalThis as unknown as { __asked: string[] }).__asked;
    expect(asked.filter((p) => p.startsWith('/oh/data/'))).toEqual([]);
    expect(asked).not.toContain('/oh/weather.json');

    // And leaves nothing behind: a prospect's visit is not a school followed.
    store.rememberLeagueTable(DEMO_SLUG, 'members', []);
    for (const jar of ['season', 'weather', 'league']) {
      expect(localStorage.getItem(`oh.${jar}.${DEMO_SLUG}`), jar).toBeNull();
    }
  });

  it('leaves the kept-identity door where it was: null until the file lands', async () => {
    await load(committed());
    const { DEMO_SLUG, rosterStore } = await stores();

    expect(rosterStore.keptSchoolSports(DEMO_SLUG)).toBeNull();
    await rosterStore.loadSchoolSports(DEMO_SLUG);
    expect(rosterStore.keptSchoolSports(DEMO_SLUG)!.sports).toHaveLength(3);
  });

  it('refuses to remember a sport, so every prospect gets the hub', async () => {
    await load(committed());
    const { DEMO_SLUG, store } = await stores();
    const jar: Record<string, string> = {};
    vi.stubGlobal('localStorage', {
      getItem: (k: string) => jar[k] ?? null,
      setItem: (k: string, v: string) => {
        jar[k] = v;
      },
      removeItem: (k: string) => {
        delete jar[k];
      },
    });

    // What a seller tapping Volleyball to show a prospect does. It must leave
    // nothing behind: the hub is the screen the demo opens on, and the key
    // would outlive the visit anyway — choose()'s sweep only evicts the school
    // a reader was following, and nobody follows the demo.
    store.rememberSport(DEMO_SLUG, 'volleyball');
    expect(Object.keys(jar)).toEqual([]);
    expect(store.chosenSport(DEMO_SLUG)).toBeNull();

    // A key from some earlier build is not read either.
    jar[`oh.sport.${DEMO_SLUG}`] = 'basketball';
    expect(store.chosenSport(DEMO_SLUG)).toBeNull();
  });

  it('fills the whole conference table from the file, so the League tab draws', async () => {
    await load(committed());
    const { DEMO_SLUG, store, rosterStore } = await stores();

    const football = await rosterStore.loadSchoolRoster(DEMO_SLUG, 'football');
    const league = football!.league!;

    const { leagueTable } = await import('./leagueTable');
    const members = [DEMO_SLUG, ...league.members];
    const seasons = await Promise.all(members.map((m) => store.loadSeason(m)));
    const rows = leagueTable(seasons, members);

    // The whole conference or none of it — the rule School.tsx holds the tab
    // to. A demo that cannot fill its own table would ship a broken tab.
    expect(rows).toHaveLength(members.length);
    expect(rows).toHaveLength(6);
    expect(rows.map((r) => r.slug)).toContain(DEMO_SLUG);
  });
});

describe('a file that is not what it should be', () => {
  const mangled: Array<[string, unknown]> = [
    ['not an object', 'nope'],
    ['no slug', { ...committed(), slug: '' }],
    ['no sport names', { ...committed(), sportNames: [] }],
    ['a sport with no squad', (() => {
      const c = committed() as { sportNames: string[]; sports: Record<string, unknown> };
      return { ...c, sports: { ...c.sports, football: { players: [], schedule: null } } };
    })()],
    ['a sport the names promise and the file has not got', (() => {
      const c = committed() as { sportNames: string[] };
      return { ...c, sportNames: [...c.sportNames, 'lacrosse'] };
    })()],
    ['seasons that are not a map of seasons', { ...committed(), seasons: ['nope'] }],
    ['a baked season with no games', (() => {
      const c = committed() as { slug: string };
      return { ...c, seasons: { [c.slug]: { school: {}, games: null } } };
    })()],
  ];

  it.each(mangled)('reads %s as no demo rather than throwing', async (_label, body) => {
    const { loadDemo } = await load(body);
    await expect(loadDemo()).resolves.toBeNull();
  });

  it('drops a forecast it cannot trust without losing the demo with it', async () => {
    const { loadDemo } = await load({ ...committed(), weather: { date: '2026-09-25' } });
    const demo = await loadDemo();

    expect(demo).not.toBeNull();
    expect(demo!.weather).toBeNull();
  });

  it('reads a file that will not come at all as no demo', async () => {
    vi.resetModules();
    vi.stubGlobal('location', { pathname: '/oh/demo/', search: '' });
    vi.stubGlobal(
      'fetch',
      vi.fn(async () => {
        throw new Error('no signal');
      }),
    );
    const { loadDemo } = await import('./demo');
    await expect(loadDemo()).resolves.toBeNull();
  });
});
